INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('4fe47269-be38-553b-b8c8-cfc330c282fd', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'fe29b87b-2a22-5e93-887b-c03035b69777', 'Kombucha Ổi Hồng', 'ngụm đầu tiên,bạn sẽ cảm nhận được vị chua thanh lên men đặc trưng của kombucha,sau đó là vị ngọt và mùi thơm của ổi hồng bung tỏa.Một chút sủi bọt nhẹ làm tăng cảm giác sảng khoái.không chỉ ngon mà còn tốt cho hệ tiêu hóa,làm đẹp da,hỗ trợ thải độc.', 39000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vswt0l1fuq4e@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177249385', 45) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('0140f3a2-c7de-5b8a-b8b3-34e0d9b4cc63', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'fe29b87b-2a22-5e93-887b-c03035b69777', 'Kombucha Cam Đào', 'Vị ngọt thanh, thơm dịu của đào chín, hòa quyện cùng hương cam tươi mát, tạo nên một hậu vị sảng khoái, dễ chịu.Có chút gas tự nhiên tạo cảm giác sủi bọt nhẹ khi uống, tương tự soda nhưng lành mạnh hơn', 39000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vsytl6u5xjcf@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177249552', 42) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('60117a0e-094b-5b6e-bb1d-3b5d13abdac9', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'fe29b87b-2a22-5e93-887b-c03035b69777', 'Kombucha Vải Hoa Hồng', 'là một thức uống lên men thanh mát, mang vẻ đẹp nhẹ nhàng, lãng mạn với sự hòa quyện độc đáo giữa vải ngọt dịu, hương hoa hồng thanh thoát, và kombucha sủi nhẹ. Vừa detox cơ thể, vừa làm dịu tâm trí – đúng chuẩn “trà đẹp da, nhẹ người, sáng lòng', 39000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vsw581uv5w37@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177230615', 39) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('e8665c8b-9dde-5f42-bb42-10118b0464b1', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'fe29b87b-2a22-5e93-887b-c03035b69777', 'Kombucha Dâu Tằm Đác Đác', 'Kombucha Dâu Tằm Đác Đác là sự kết hợp giữa hương vị chua thanh của kombucha, vị ngọt dịu của dâu tằm và sự dai giòn sần sật của hạt đác.Đây là thức uống lên men tốt cho sức khỏe, hỗ trợ tiêu hóa, thanh lọc cơ thể và mang lại cảm giác sảng khoái.', 39000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vt84hkr5aa9f@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177249627', 36) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('3c80fd5b-1d30-59f4-a8f6-af10537c25f9', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'fe29b87b-2a22-5e93-887b-c03035b69777', 'Kombucha Xoài Kiwi', 'là một loại trà lên men có hương vị tươi mát, kết hợp giữa vị ngọt thanh của xoài chín và chút chua nhẹ của kiwi.Giúp hỗ trợ tiêu hóa nhờ men vi sinh tự nhiên trong kombucha.', 39000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m9tol32awbcea1@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177249590', 33) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('38c2a740-f2ec-5824-8217-5e48cac656e2', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'fe29b87b-2a22-5e93-887b-c03035b69777', 'Kombucha Chanh Dây', 'Sự kết hợp hoàn hảo giữa vị chua thanh nhẹ, chút ngọt dịu tự nhiên với hậu vị trà kombucha lên men, vừa thanh nhẹ, vừa thơm thoảng chút men dịu dàng. Kombucha Chanh Dây còn tốt cho tiêu hóa, giúp cơ thể sảng khoái, nhẹ nhàng hơn..', 39000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m9toociuyypw08@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177249654', 30) ON CONFLICT DO NOTHING;
INSERT INTO menu_category (id, store_id, name, sort_order) VALUES ('ecb673cd-93aa-5379-8540-059e451cc06c', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'CAFE NGON MÊ', 3) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('b65d383d-a90e-5dcf-b1d7-50317531d551', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'ecb673cd-93aa-5379-8540-059e451cc06c', 'Cafe Sữa Ngon', 'Ly cà phê phin sữa đá Arabica & Robusta không chỉ mang nét truyền thống mà còn có sự kết hợp hiện đại, tạo nên một trải nghiệm thưởng thức đậm đà, cuốn hút.', 25000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vh01poqi4k64@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177233184', 27) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('0e722b8d-dd06-5ab1-9e46-1d7da61e3fab', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'ecb673cd-93aa-5379-8540-059e451cc06c', 'Cafe đen', 'Pha phin truyền thống để giữ trọn hương vị cà phê nguyên bản, từ hạt Arabica & Robusta, là sự lựa chọn lý tưởng cho những ai yêu thích cà phê nguyên bản, giúp tỉnh táo và tận hưởng trọn vẹn tinh hoa của từng loại hạt.', 20000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vgwfl95kdqa2@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177230606', 24) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('d1e06ff7-daf1-5e1c-a970-10445edb582e', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'ecb673cd-93aa-5379-8540-059e451cc06c', 'Cafe Sữa Tươi Caramel Muối', 'Một ngụm sữa tươi cà phê caramel muối như một bản hòa tấu ngắn nhưng ấn tượng – mở đầu bằng vị ngọt dịu và béo mịn, cao trào là cà phê đậm đà, kết thúc bằng hậu vị mằn mặn tinh tế. Không chỉ ngon miệng mà còn mang đến cảm giác “tỉnh táo nhưng dễ chịu', 35000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vhda9vdwsk10@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177233294', 21) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('e455fd36-8ebc-5d54-af36-747cc8c7b7a0', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'ecb673cd-93aa-5379-8540-059e451cc06c', 'Bạc Xỉu Ngon Mê', 'ly bạc xỉu mát lạnh vào buổi sáng hoặc trưa nóng sẽ giúp bạn tỉnh táo nhưng vẫn dễ chịu, không bị “nặng đô” như cà phê đen.', 25000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vh4qr1dc3m53@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177233203', 18) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('b0b686da-3d92-52c3-90dd-2378852eefed', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'ecb673cd-93aa-5379-8540-059e451cc06c', 'Cafe Phô Mai', 'Nhấp một ngụm, bạn sẽ cảm nhận được sự chuyển đổi kỳ diệu của hương vị: đầu tiên là vị đắng nhẹ của cà phê, sau đó là độ béo ngậy tan chảy của phô mai, cuối cùng để lại một chút mặn dịu tinh tế, như một nụ hôn ngọt ngào đọng lại nơi đầu lưỡi.', 29000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vh6q5gx7wk41@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177233233', 15) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('5c943855-5d92-5db5-a0d3-c92e76786554', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'ecb673cd-93aa-5379-8540-059e451cc06c', 'Cafe Kem Dừa', 'sự kết hợp hoàn hảo giữa vị đắng đậm đà của cà phê và lớp kem dừa béo mịn, Một thức uống không chỉ thơm ngon mà còn khiến bạn say mê ngay từ ngụm đầu tiên!', 32000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vh9e3mig07cd@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177233268', 12) ON CONFLICT DO NOTHING;
INSERT INTO menu_category (id, store_id, name, sort_order) VALUES ('138049c4-d4f3-55e4-9d35-bb8871861b07', 'cffafe92-0351-5d43-be6f-f9416d19b03b', 'LATTE NGỌT NGÀO', 4) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('823f4ee5-b45a-59d6-8576-0fdbc2e37c85', 'cffafe92-0351-5d43-be6f-f9416d19b03b', '138049c4-d4f3-55e4-9d35-bb8871861b07', 'Matcha latte', 'Matcha latte có vị thanh mát của Matcha Đài kết hợp với sự béo ngậy của sữa tươi Úc tạo cảm giác dễ chịu và thư giãn.', 35000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vhjawubm9ad1@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177230609', 9) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('ba9d6010-34d8-5e13-8289-ac19ab4d74bc', 'cffafe92-0351-5d43-be6f-f9416d19b03b', '138049c4-d4f3-55e4-9d35-bb8871861b07', 'SoCola Latte', 'là một món uống siêu “gây nghiện” cho những ai thích vị ngọt béo mát lạnh, có chút đắng nhẹ của cà phê và mùi thơm ngậy từ socola.', 35000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vhqkrf6ete00@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177233436', 6) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('39656cf5-2088-5bbb-b6bd-5e4e856461cc', 'cffafe92-0351-5d43-be6f-f9416d19b03b', '138049c4-d4f3-55e4-9d35-bb8871861b07', 'Latte Bơ Đậu Phộng', 'Hương thơm nồng nàn của cà phê quyện với vị bùi béo đặc trưng của bơ đậu phộng, thêm chút sữa tươi mịn màng, mang đến một thức uống vừa đậm đà vừa ngọt dịu, cực kỳ kích thích vị giác.', 39000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vi6bkznvqm61@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177233569', 3) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('9ace6ca2-3aa3-5c38-9656-154a5195acdf', 'cffafe92-0351-5d43-be6f-f9416d19b03b', '138049c4-d4f3-55e4-9d35-bb8871861b07', 'Latte Nguyên Vị Kem cheese', 'Khi nhấp môi, lớp kem cheese tan chảy, quyện cùng vị cà phê ấm áp, tạo nên một cảm giác bồng bềnh như lạc vào đám mây hương vị.', 40000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vi3by77m9u9a@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177233550', 5) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('2cf10410-7703-5b77-86fd-9d4b3f2e9a86', 'cffafe92-0351-5d43-be6f-f9416d19b03b', '138049c4-d4f3-55e4-9d35-bb8871861b07', 'Sữa tươi Kem Matcha', 'Sữa tươi mát lạnh kết hợp cùng sốt kem matcha thơm lừng, béo nhẹ, đánh tan cơn khát ngày nắng nóng. Lớp sốt matcha sánh mịn, rưới lên sữa tươi nguyên chất, vừa nhìn đã mê – vừa uống là ghiền!', 40000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m9gy2mgmbb7rcb@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177496106', 5) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('ff586cd1-7efc-572a-885b-25d48358a6dd', 'cffafe92-0351-5d43-be6f-f9416d19b03b', '138049c4-d4f3-55e4-9d35-bb8871861b07', 'Dừa Non Matcha', 'Ngay từ ngụm đầu tiên, Coco Matcha Cloud mang đến cảm giác như “uống một áng mây”: thanh khiết từ matcha, béo thơm từ dừa, mềm mại từ lớp kem. Rất thích hợp cho những ai yêu thích đồ uống thanh tao, ít ngọt, mang đậm chất Nhật – nhiệt đới.', 40000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vhll2m3a13e4@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177233354', 5) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('cccd1313-000c-5bc5-84ec-abac0bfd7433', 'cffafe92-0351-5d43-be6f-f9416d19b03b', '138049c4-d4f3-55e4-9d35-bb8871861b07', 'Sữa Tươi Kem Choco', 'một món đồ uống ngọt ngào,béo mịn và cực kỳ "gây nghiện" cho những tín đồ socola.Đây là sự kết hợp giữa sữa tươi, socola đậm đà và một lớp kem mây bồng bềnh bên trên – tạo nên cảm giác vừa ấm áp, mềm mại như mây,  đậm vị như một thanh socola tan chảy', 35000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m8vhwu3dfjwid6@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177233509', 5) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('e8544ccb-9833-5533-9cdc-e118c5c69d50', 'cffafe92-0351-5d43-be6f-f9416d19b03b', '138049c4-d4f3-55e4-9d35-bb8871861b07', 'Cold Whisk Matcha', 'Đây là phiên bản “matcha lạnh” hiện đại, Thức uống mát lạnh cho ngày nắng, với vị matcha ngọt hậu tự nhiên, không đắng gắt. Lớp bọt mịn như sương, nhấp một ngụm là thấy xanh tươi, nhẹ người..', 40000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ras8-mav8wsvkru6k4f@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '178417255', 5) ON CONFLICT DO NOTHING;
