INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('42e94dc9-4a5d-5973-8a38-4844a3b2c0ca', '0cedf0f9-d596-527e-8cb0-7a263ff4cb53', 'b28a903b-2bf4-5e14-8ca3-452dc5f766d3', 'Trà Tắc', 'Món truyền thống luôn được yêu thích – thơm tắc, nhẹ trà, phù hợp giải khát vào mùa hè nắng nóng.', 20000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m9mzw66aq150e8@resize_ss400x400!@crop_w400_h400_cT', 'available', TRUE, '177267428', 57) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('5ebfe9dc-6b72-5efe-98cf-706798726656', '0cedf0f9-d596-527e-8cb0-7a263ff4cb53', 'b28a903b-2bf4-5e14-8ca3-452dc5f766d3', 'Rau Má Đậu Xanh', 'Rau má mát lành kết hợp cùng đậu xanh béo bùi thêm chút sữa cho vừa vị - uống khỏe, ngon miệng.', 24000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m9n0g3bj9lay90@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177267418', 54) ON CONFLICT DO NOTHING;
