INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('25b42718-4048-551e-be2b-aef7725ffa08', '0cedf0f9-d596-527e-8cb0-7a263ff4cb53', 'b28a903b-2bf4-5e14-8ca3-452dc5f766d3', 'Sâm Dứa Sữa - kèm trân châu trắng', 'Hương sâm dứa thơm dịu, hòa quyện cùng sữa béo nhẹ nhàng – mát lạnh, dễ uống.', 24000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ras8-mavif0filkuw2d@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177267426', 48) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('85cf80af-7ff3-57c9-b7a6-f1826e7ea047', '0cedf0f9-d596-527e-8cb0-7a263ff4cb53', 'b28a903b-2bf4-5e14-8ca3-452dc5f766d3', 'Matcha Latte', 'Matcha nguyên chất, đậm vị trà nhưng không chát, sữa tươi cân bằng độ ngọt – món "must try" với tín đồ matcha.', 28000, NULL, 'https://mms.img.susercontent.com/vn-11134517-7ras8-mauc6ny6yfm4f9@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '178370580', 45) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('099e3b71-77d2-57a9-8756-91c6c790f735', '0cedf0f9-d596-527e-8cb0-7a263ff4cb53', 'b28a903b-2bf4-5e14-8ca3-452dc5f766d3', 'Cà phê sữa (pha máy) – Thơm nồng, đậm vị, ngọt dịu', 'Cà phê pha từ máy epresso kết hợp cùng sữa đặc – đậm vị, béo nhẹ, thơm nồng nàn. Phù hợp với mọi độ tuổi.', 26000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m9n2cvz4zb72b3@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177267406', 42) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('56e84ab5-8aa1-5d49-b376-5a7bac11aee2', '0cedf0f9-d596-527e-8cb0-7a263ff4cb53', 'b28a903b-2bf4-5e14-8ca3-452dc5f766d3', 'Cà phê đá pha máy', 'Loại cà phê được pha bằng máy pha cà phê espresso, với nguyên liệu chính là cà phê hạt rang đặc biệt đã được xay nhuyễn, đậm đà, thơm ngon. Phù hợp với người có gu cà phê đậm chuẩn vị.', 20000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ra0g-m9n2dj6b15667a@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177267407', 39) ON CONFLICT DO NOTHING;
INSERT INTO menu_item (id, store_id, menu_category_id, name, description, price, discount_price, image_url, status, is_signature, external_id, order_count) VALUES ('f34a77d9-7f97-591b-9e91-2f3f06d33527', '0cedf0f9-d596-527e-8cb0-7a263ff4cb53', 'b28a903b-2bf4-5e14-8ca3-452dc5f766d3', 'Tắc Xí Muội', 'Chua chua của tắc, mặn ngọt của xí muội – kiểu đồ uống dễ ghiền, mát cổ, ngon miệng.', 20000, NULL, 'https://mms.img.susercontent.com/vn-11134505-7ras8-mavipen90og137@resize_ss400x400!@crop_w400_h400_cT', 'available', FALSE, '177267432', 36) ON CONFLICT DO NOTHING;
