-- ============================================================================
-- EXE101 / LocalEats — FULL DATABASE SCRIPT (PostgreSQL 15+ / Supabase)
-- ----------------------------------------------------------------------------
-- Nguon suy luan:
--   * LocalEeats/LocalEats-DDL-PostgreSQL.sql  (12 bang loi, GIU NGUYEN ten cot de
--     khop Entity Spring Boot AppUser / OtpVerification, ddl-auto=validate)
--   * Front-end React (localeats/src): Map, HotList, AI, VIP, Saved, Review, Live,
--     Trip Planner, Mystery Food, Merchant Dashboard (7 tab), Admin Dashboard (16 tab)
--   * restaurants_with_dishes.csv (ShopeeFood: restaurant + dishes_json)
--
-- Chay 1 lan tren DB TRONG. Neu DB da co 12 bang cu: chay phan "RESET" ben duoi
-- (CHI dung cho dev) hoac tao schema moi.
--
-- Muc luc:
--   0  Extensions        1  Enums            2  Functions chung
--   3  Nhom ACCOUNT      4  Nhom STORE/MENU  5  Nhom REVIEW/SOCIAL
--   6  Nhom GPS & NAVIGATION (tim duong + phat hien di chuyen/den quan)
--   7  Nhom TRIP / AI / CHALLENGE / LIVE
--   8  Nhom THANH TOAN / GOI / QUANG CAO / VOUCHER
--   9  Nhom ADMIN (KYC-ATTP, fraud, KOL, RBAC, audit, API, routing node)
--   10 Views & Functions nghiep vu   11 Seed data
-- ============================================================================

-- ---------------------------------------------------------------------------
-- (TUY CHON - CHI DEV) RESET toan bo schema public. Bo comment neu can.
-- ---------------------------------------------------------------------------
-- DROP SCHEMA public CASCADE; CREATE SCHEMA public;
-- GRANT ALL ON SCHEMA public TO postgres; GRANT ALL ON SCHEMA public TO public;

-- ============================================================================
-- 0. EXTENSIONS
-- ============================================================================
-- gen_random_uuid() co san tu PostgreSQL 13+ (khong can pgcrypto)
-- (Khong dung PostGIS: Termux/VPS dien thoai khong co goi. Khoang cach tinh bang
--  fn_haversine_m() + bounding box tren index (latitude, longitude). Co the bat PostGIS sau.)
CREATE EXTENSION IF NOT EXISTS pg_trgm;    -- tim kiem ten quan gan dung (LIKE/similarity)

-- ============================================================================
-- 1. ENUM TYPES
-- ============================================================================
-- ---- Giu nguyen tu DDL cu ----
CREATE TYPE user_role              AS ENUM ('user', 'staff', 'admin');
CREATE TYPE subscription_type      AS ENUM ('user_premium', 'store_analytics');
CREATE TYPE subscription_status    AS ENUM ('active', 'expired', 'cancelled');
CREATE TYPE payment_status         AS ENUM ('pending', 'success', 'failed');
CREATE TYPE owner_profile_status   AS ENUM ('pending', 'verified', 'rejected');
CREATE TYPE verification_status    AS ENUM ('pending', 'approved', 'rejected');
CREATE TYPE store_status           AS ENUM ('pending', 'active', 'hidden', 'removed');
CREATE TYPE review_status          AS ENUM ('visible', 'hidden', 'flagged');
CREATE TYPE report_target_type     AS ENUM ('store', 'review', 'user');
CREATE TYPE report_status          AS ENUM ('pending', 'resolved', 'dismissed');
CREATE TYPE owner_warning_severity AS ENUM ('warning', 'final_warning', 'banned');

-- ---- Moi ----
CREATE TYPE transport_mode   AS ENUM ('bike', 'car', 'walk');
-- Vong doi 1 phien di chuyen toi quan (state machine o muc 6):
--   started   : user vua bam "Chi duong" (da luu vi tri xuat phat)
--   moving    : GPS roi khoi diem xuat phat > nguong => dang di chuyen
--   near_store: dang trong ban kinh geofence cua quan (chua du thoi gian dung)
--   arrived   : dung yen trong geofence >= 10 phut => DA DEN QUAN (tao store_visit)
--   cancelled : user huy / bat chi duong moi
--   expired   : qua thoi gian toi da khong co ping / khong den
CREATE TYPE nav_session_status AS ENUM ('started','moving','near_store','arrived','cancelled','expired');
CREATE TYPE nav_end_reason     AS ENUM ('dwell_confirmed','user_cancelled','new_session','timeout','gps_lost','manual_checkin');
CREATE TYPE store_event_type   AS ENUM ('impression','view','search_hit','save','unsave','share','route_request','navigate_start','arrive','call','vote');
CREATE TYPE ad_campaign_type   AS ENUM ('discount_percent','discount_amount','gift','checkin_bonus','sponsored_pin');
CREATE TYPE ad_campaign_status AS ENUM ('draft','pending_review','running','paused','completed','rejected');
CREATE TYPE voucher_status     AS ENUM ('claimed','redeemed','expired');
CREATE TYPE ad_event_type      AS ENUM ('impression','click','claim','redeem');
CREATE TYPE live_status        AS ENUM ('scheduled','live','ended');
CREATE TYPE menu_item_status   AS ENUM ('available','sold_out','hidden');
CREATE TYPE trip_status        AS ENUM ('draft','saved','in_progress','completed','cancelled');
CREATE TYPE kol_tier           AS ENUM ('rookie','rising','pro','elite');
CREATE TYPE fraud_status       AS ENUM ('open','investigating','confirmed','dismissed');
CREATE TYPE document_type      AS ENUM ('business_license','food_safety_cert','tax_code','other');
CREATE TYPE notification_type  AS ENUM ('system','arrived','voucher','review_reply','store_approved','store_rejected','warning','promo');
CREATE TYPE invoice_status     AS ENUM ('draft','issued','paid','cancelled');
CREATE TYPE node_status        AS ENUM ('online','degraded','offline','maintenance');
CREATE TYPE route_provider     AS ENUM ('osrm','graphhopper','valhalla','google','internal_astar');

-- ============================================================================
-- 2. FUNCTIONS DUNG CHUNG
-- ============================================================================
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ============================================================================
-- 3. NHOM ACCOUNT
-- ============================================================================
-- 3.1 app_user  (KHOP Entity AppUser — khong doi ten cot)
CREATE TABLE app_user (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    phone         VARCHAR(15),
    email         VARCHAR(255),
    password_hash VARCHAR(255) NOT NULL,
    role          user_role NOT NULL DEFAULT 'user',
    is_verified   BOOLEAN NOT NULL DEFAULT FALSE,
    is_premium    BOOLEAN NOT NULL DEFAULT FALSE,
    is_locked     BOOLEAN NOT NULL DEFAULT FALSE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_user_contact CHECK (phone IS NOT NULL OR email IS NOT NULL),
    CONSTRAINT uq_user_phone UNIQUE (phone),
    CONSTRAINT uq_user_email UNIQUE (email)
);
CREATE TRIGGER trg_app_user_updated_at BEFORE UPDATE ON app_user
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX idx_app_user_role ON app_user(role);
COMMENT ON TABLE app_user IS 'Tai khoan goc cho user/staff/admin. Chu quan = user co them store_owner_profile.';

-- 3.2 user_otp_verification (KHOP Entity OtpVerification)
CREATE TABLE user_otp_verification (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    otp_code_hash VARCHAR(255) NOT NULL,
    channel       VARCHAR(10) NOT NULL CHECK (channel IN ('phone','email')),
    expires_at    TIMESTAMPTZ NOT NULL,
    consumed_at   TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_otp_user_id ON user_otp_verification(user_id);

-- 3.3 user_profile — thong tin hien thi + so thich (FE: Navbar, AI mood, Saved)
CREATE TABLE user_profile (
    user_id        UUID PRIMARY KEY REFERENCES app_user(id) ON DELETE CASCADE,
    display_name   VARCHAR(100),
    avatar_url     TEXT,
    bio            TEXT,
    taste_tags     TEXT[] NOT NULL DEFAULT '{}',        -- "Cay nong am bung", "Troi mua lanh"...
    default_mode   transport_mode NOT NULL DEFAULT 'bike',
    home_latitude  NUMERIC(9,6),
    home_longitude NUMERIC(9,6),
    share_location BOOLEAN NOT NULL DEFAULT TRUE,       -- user dong y cho he thong theo doi GPS khi chi duong
    locale         VARCHAR(10) NOT NULL DEFAULT 'vi',
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TRIGGER trg_user_profile_updated_at BEFORE UPDATE ON user_profile
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 3.4 refresh_token / thiet bi (JWT refresh, push)
CREATE TABLE user_session (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    family_id     UUID NOT NULL,                 -- 1 chuoi refresh token (rotation); reuse => thu hoi ca chuoi
    refresh_hash  VARCHAR(64) NOT NULL,          -- SHA-256 hex cua refresh token (khong luu token tho)
    device_info   TEXT,
    ip_address    VARCHAR(45),
    expires_at    TIMESTAMPTZ NOT NULL,
    revoked_at    TIMESTAMPTZ,
    replaced_at   TIMESTAMPTZ,                   -- da duoc doi sang token moi (rotation)
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_user_session_hash UNIQUE (refresh_hash)
);
CREATE INDEX idx_user_session_user ON user_session(user_id);
CREATE INDEX idx_user_session_family ON user_session(family_id);

CREATE TABLE push_device (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    platform    VARCHAR(10) NOT NULL CHECK (platform IN ('web','android','ios')),
    token       TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_push_token UNIQUE (token)
);

-- 3.5 Goi dich vu (thay vi hard-code gia)
CREATE TABLE subscription_plan (
    id            SMALLSERIAL PRIMARY KEY,
    code          VARCHAR(50) NOT NULL UNIQUE,
    type          subscription_type NOT NULL,
    name          VARCHAR(150) NOT NULL,
    price         NUMERIC(12,2) NOT NULL CHECK (price >= 0),
    duration_days INTEGER NOT NULL CHECK (duration_days > 0),
    features      JSONB NOT NULL DEFAULT '{}',
    is_active     BOOLEAN NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 3.6 user_subscription (giu cot cu + them plan_id)
CREATE TABLE user_subscription (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id        UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    plan_id        SMALLINT REFERENCES subscription_plan(id),
    type           subscription_type NOT NULL DEFAULT 'user_premium',
    start_date     TIMESTAMPTZ NOT NULL DEFAULT now(),
    end_date       TIMESTAMPTZ NOT NULL,
    status         subscription_status NOT NULL DEFAULT 'active',
    payment_status payment_status NOT NULL DEFAULT 'pending',
    price_paid     NUMERIC(12,2) NOT NULL CHECK (price_paid >= 0),
    payment_ref    VARCHAR(100),
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_sub_dates CHECK (end_date > start_date),
    CONSTRAINT chk_sub_active_requires_paid CHECK (status <> 'active' OR payment_status = 'success')
);
CREATE INDEX idx_user_subscription_user_id ON user_subscription(user_id);
CREATE INDEX idx_user_subscription_status  ON user_subscription(status, end_date);

-- 3.7 Chu quan
CREATE TABLE store_owner_profile (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id              UUID NOT NULL UNIQUE REFERENCES app_user(id) ON DELETE CASCADE,
    full_name            VARCHAR(255) NOT NULL,
    cccd_number_hash     CHAR(64) NOT NULL,
    status               owner_profile_status NOT NULL DEFAULT 'pending',
    business_license_url TEXT,
    tax_code             VARCHAR(20),                    -- MST (FE: Invoices tab)
    business_name        VARCHAR(255),
    is_business_verified BOOLEAN NOT NULL DEFAULT FALSE,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_owner_cccd_hash UNIQUE (cccd_number_hash)
);
CREATE TRIGGER trg_store_owner_profile_updated_at BEFORE UPDATE ON store_owner_profile
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX idx_owner_profile_status ON store_owner_profile(status);

CREATE TABLE identity_verification (
    id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_owner_profile_id UUID NOT NULL UNIQUE REFERENCES store_owner_profile(id) ON DELETE CASCADE,
    image_path_encrypted   TEXT NOT NULL,
    submitted_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    status                 verification_status NOT NULL DEFAULT 'pending',
    reviewed_by            UUID REFERENCES app_user(id) ON DELETE SET NULL,
    reviewed_at            TIMESTAMPTZ,
    rejection_reason       TEXT,
    image_delete_at        TIMESTAMPTZ,
    image_deleted          BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT chk_verification_review CHECK (status = 'pending' OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL))
);
CREATE INDEX idx_identity_verification_status ON identity_verification(status);
CREATE INDEX idx_identity_verification_delete_due ON identity_verification(image_delete_at) WHERE image_deleted = FALSE;

CREATE TABLE owner_warning (
    id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_owner_profile_id UUID NOT NULL REFERENCES store_owner_profile(id) ON DELETE CASCADE,
    issued_by              UUID NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT,
    severity               owner_warning_severity NOT NULL DEFAULT 'warning',
    reason                 TEXT NOT NULL,
    created_at             TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_owner_warning_profile_id ON owner_warning(store_owner_profile_id);

-- ============================================================================
-- 4. NHOM STORE / MENU
-- ============================================================================
-- 4.1 category (FE: filter Phở/Bánh mì/Ốc..., mood AI, icon Merchant Settings)
CREATE TABLE category (
    id         SMALLSERIAL PRIMARY KEY,
    code       VARCHAR(50) NOT NULL UNIQUE,
    name       VARCHAR(100) NOT NULL,
    icon       VARCHAR(50),                 -- material symbol (ramen_dining, coffee...)
    kind       VARCHAR(10) NOT NULL DEFAULT 'cuisine' CHECK (kind IN ('cuisine','mood','tag')),
    sort_order INTEGER NOT NULL DEFAULT 0
);

-- 4.2 store
CREATE TABLE store (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id        UUID NOT NULL REFERENCES store_owner_profile(id) ON DELETE RESTRICT,
    name            VARCHAR(255) NOT NULL,
    name_en         VARCHAR(255),
    address         VARCHAR(500) NOT NULL,
    district        VARCHAR(100),
    city            VARCHAR(100) NOT NULL DEFAULT 'Ho Chi Minh',
    phone           VARCHAR(20),
    latitude        NUMERIC(9,6) NOT NULL,
    longitude       NUMERIC(9,6) NOT NULL,
    opening_hours   JSONB,                          -- {"mon":"07:00-22:00",...}
    open_time       TIME,                           -- gio mo mac dinh (FE: openNow, closeAt)
    close_time      TIME,
    description     TEXT,
    specialty       TEXT,                           -- mon dac trung (FE: specialty)
    price_min       INTEGER CHECK (price_min >= 0), -- VND (FE: "65.000d - 90.000d")
    price_max       INTEGER CHECK (price_max >= 0),
    avg_wait_minutes INTEGER,                       -- FE: waitTime
    logo_url        TEXT,
    cover_image_url TEXT,
    status          store_status NOT NULL DEFAULT 'pending',
    approved_by     UUID REFERENCES app_user(id) ON DELETE SET NULL,
    approved_at     TIMESTAMPTZ,
    last_edited_at  TIMESTAMPTZ,
    -- cot tong hop (duoc cap nhat bang trigger/job) de list nhanh
    rating_avg      NUMERIC(3,2) NOT NULL DEFAULT 0,
    review_count    INTEGER NOT NULL DEFAULT 0,
    vote_count      INTEGER NOT NULL DEFAULT 0,
    visit_count     INTEGER NOT NULL DEFAULT 0,
    is_sponsored    BOOLEAN NOT NULL DEFAULT FALSE,
    -- dong bo du lieu ngoai (ShopeeFood CSV)
    external_source VARCHAR(30),
    external_id     VARCHAR(50),
    source_url      TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_store_latitude  CHECK (latitude  BETWEEN -90  AND 90),
    CONSTRAINT chk_store_longitude CHECK (longitude BETWEEN -180 AND 180),
    CONSTRAINT chk_store_price CHECK (price_max IS NULL OR price_min IS NULL OR price_max >= price_min),
    CONSTRAINT uq_store_external UNIQUE (external_source, external_id)
);
CREATE TRIGGER trg_store_updated_at BEFORE UPDATE ON store
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX idx_store_owner_id ON store(owner_id);
CREATE INDEX idx_store_status   ON store(status);
CREATE INDEX idx_store_lat_lng  ON store(latitude, longitude);
CREATE INDEX idx_store_name_trgm ON store USING GIN (lower(name) gin_trgm_ops);
CREATE INDEX idx_store_district ON store(district);

CREATE TABLE store_category (
    store_id    UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    category_id SMALLINT NOT NULL REFERENCES category(id) ON DELETE CASCADE,
    is_primary  BOOLEAN NOT NULL DEFAULT FALSE,
    PRIMARY KEY (store_id, category_id)
);
CREATE INDEX idx_store_category_cat ON store_category(category_id);

CREATE TABLE store_image (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id   UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    url        TEXT NOT NULL,
    caption    VARCHAR(255),
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_store_image_store ON store_image(store_id);

-- 4.3 Menu (FE: MerchantMenuTab, CSV dishes_json)
CREATE TABLE menu_category (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id   UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    name       VARCHAR(150) NOT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT uq_menu_category UNIQUE (store_id, name)
);

CREATE TABLE menu_item (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id         UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    menu_category_id UUID REFERENCES menu_category(id) ON DELETE SET NULL,
    name             VARCHAR(255) NOT NULL,
    description      TEXT,
    price            INTEGER NOT NULL CHECK (price >= 0),
    discount_price   INTEGER CHECK (discount_price >= 0),
    image_url        TEXT,
    status           menu_item_status NOT NULL DEFAULT 'available',
    is_signature     BOOLEAN NOT NULL DEFAULT FALSE,    -- mon dac trung / best seller
    tags             TEXT[] NOT NULL DEFAULT '{}',      -- cay, nuoc leo, healthy... (AI goi y)
    external_id      VARCHAR(50),
    order_count      INTEGER NOT NULL DEFAULT 0,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_discount_lt_price CHECK (discount_price IS NULL OR discount_price <= price)
);
CREATE TRIGGER trg_menu_item_updated_at BEFORE UPDATE ON menu_item
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX idx_menu_item_store ON menu_item(store_id);
CREATE INDEX idx_menu_item_name_trgm ON menu_item USING GIN (lower(name) gin_trgm_ops);

-- 4.4 Giay to quan (KYC & ATTP — Admin KYC tab)
CREATE TABLE store_document (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id         UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    type             document_type NOT NULL,
    file_url         TEXT NOT NULL,
    status           verification_status NOT NULL DEFAULT 'pending',
    reviewed_by      UUID REFERENCES app_user(id) ON DELETE SET NULL,
    reviewed_at      TIMESTAMPTZ,
    rejection_reason TEXT,
    expires_at       DATE,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_store_document_store  ON store_document(store_id);
CREATE INDEX idx_store_document_status ON store_document(status);

-- 4.5 Goi thong ke 235k
CREATE TABLE store_stat_subscription (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id       UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    plan_id        SMALLINT REFERENCES subscription_plan(id),
    start_date     TIMESTAMPTZ NOT NULL DEFAULT now(),
    end_date       TIMESTAMPTZ NOT NULL,
    status         subscription_status NOT NULL DEFAULT 'active',
    payment_status payment_status NOT NULL DEFAULT 'pending',
    price_paid     NUMERIC(12,2) NOT NULL CHECK (price_paid >= 0),
    payment_ref    VARCHAR(100),
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_store_sub_dates CHECK (end_date > start_date),
    CONSTRAINT chk_store_sub_active_requires_paid CHECK (status <> 'active' OR payment_status = 'success')
);
CREATE INDEX idx_store_stat_sub_store_id ON store_stat_subscription(store_id);
CREATE INDEX idx_store_stat_sub_status   ON store_stat_subscription(status, end_date);

-- 4.6 Thong ke theo ngay (cap nhat boi job tong hop store_event / store_visit)
CREATE TABLE store_visit_stat (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id              UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    stat_date             DATE NOT NULL,
    search_count          INTEGER NOT NULL DEFAULT 0 CHECK (search_count >= 0),
    view_count            INTEGER NOT NULL DEFAULT 0 CHECK (view_count >= 0),
    route_requested_count INTEGER NOT NULL DEFAULT 0 CHECK (route_requested_count >= 0),
    visit_confirmed_count INTEGER NOT NULL DEFAULT 0 CHECK (visit_confirmed_count >= 0),
    avg_dwell_seconds     INTEGER,
    peak_hour_histogram   JSONB,
    CONSTRAINT uq_store_visit_stat_day UNIQUE (store_id, stat_date)
);
CREATE INDEX idx_store_visit_stat_store_date ON store_visit_stat(store_id, stat_date);

-- ============================================================================
-- 5. NHOM REVIEW / SOCIAL
-- ============================================================================
CREATE TABLE review (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id          UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    store_id         UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    rating           SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    title            VARCHAR(255),
    comment          TEXT,
    image_urls       TEXT[],
    status           review_status NOT NULL DEFAULT 'visible',
    hidden_reason    TEXT,
    is_verified_visit BOOLEAN NOT NULL DEFAULT FALSE,   -- "Da xac thuc dung tai quan" (co store_visit)
    like_count       INTEGER NOT NULL DEFAULT 0,
    ai_sentiment     NUMERIC(4,3),                      -- -1..1 (Review Sentinel)
    ai_spam_score    NUMERIC(4,3),                      -- 0..1
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_review_user_store UNIQUE (user_id, store_id)
);
CREATE TRIGGER trg_review_updated_at BEFORE UPDATE ON review
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX idx_review_store_id ON review(store_id);
CREATE INDEX idx_review_user_id  ON review(user_id);
CREATE INDEX idx_review_status   ON review(status);

CREATE TABLE review_like (
    review_id  UUID NOT NULL REFERENCES review(id) ON DELETE CASCADE,
    user_id    UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (review_id, user_id)
);

CREATE TABLE review_reply (            -- chu quan phan hoi (Merchant Reviews tab)
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    review_id  UUID NOT NULL UNIQUE REFERENCES review(id) ON DELETE CASCADE,
    owner_id   UUID NOT NULL REFERENCES store_owner_profile(id) ON DELETE CASCADE,
    content    TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE review_moderation_log (   -- AI Sentinel + staff
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    review_id  UUID NOT NULL REFERENCES review(id) ON DELETE CASCADE,
    actor_id   UUID REFERENCES app_user(id) ON DELETE SET NULL,  -- NULL = AI
    action     VARCHAR(30) NOT NULL,                            -- flag/hide/restore
    reason     TEXT,
    ai_score   NUMERIC(4,3),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE saved_store (
    user_id    UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    store_id   UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, store_id)
);
CREATE INDEX idx_saved_store_store_id ON saved_store(store_id);

-- "Binh chon HOT" (HotList: votes / trend)
CREATE TABLE store_vote (
    user_id    UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    store_id   UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    voted_on   DATE NOT NULL DEFAULT CURRENT_DATE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, store_id, voted_on)       -- moi user 1 vote/quan/ngay
);
CREATE INDEX idx_store_vote_store_date ON store_vote(store_id, voted_on);

CREATE TABLE report (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    reporter_id     UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    target_type     report_target_type NOT NULL,
    target_id       UUID NOT NULL,                  -- polymorphic, kiem tra o Service
    reason          TEXT NOT NULL,
    status          report_status NOT NULL DEFAULT 'pending',
    handled_by      UUID REFERENCES app_user(id) ON DELETE SET NULL,
    resolution_note TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    resolved_at     TIMESTAMPTZ
);
CREATE INDEX idx_report_target      ON report(target_type, target_id);
CREATE INDEX idx_report_status      ON report(status);
CREATE INDEX idx_report_reporter_id ON report(reporter_id);

CREATE TABLE notification (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    type       notification_type NOT NULL DEFAULT 'system',
    title      VARCHAR(255) NOT NULL,
    body       TEXT,
    data       JSONB,
    read_at    TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_notification_user ON notification(user_id, read_at, created_at DESC);

-- ============================================================================
-- 6. NHOM GPS & NAVIGATION  (TRAI TIM CUA APP)
-- ----------------------------------------------------------------------------
-- Luong nghiep vu:
--  1) User bam vao quan / "Chi duong"  -> backend tao nav_session(status='started'),
--     luu origin_lat/lng + route (polyline, distance, duration) tu routing engine.
--  2) App gui location_ping dinh ky (5-10s khi dang di, 30s khi dung yen).
--  3) Neu khoang cach tu ping toi origin > moving_threshold_m (mac dinh 50m)
--     voi accuracy tot -> status='moving' (dang di chuyen).
--  4) Khi ping nam trong geofence cua quan (arrive_radius_m, mac dinh 100m)
--     -> status='near_store', dat dwell_started_at + dwell_anchor (diem neo).
--     Neu ping tiep theo van trong stationary_radius_m (mac dinh 30m) quanh diem neo
--     -> tiep tuc dem. Neu vuot ra -> reset dwell_started_at.
--  5) Khi (now - dwell_started_at) >= dwell_seconds (mac dinh 600s = 10 PHUT)
--     -> status='arrived', end_reason='dwell_confirmed', INSERT store_visit,
--        tang store_visit_stat.visit_confirmed_count, mo khoa viet review "da xac thuc".
-- Cac nguong nam trong bang app_setting => chinh duoc ma khong deploy lai.
-- ============================================================================

CREATE TABLE nav_session (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id              UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    store_id             UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    status               nav_session_status NOT NULL DEFAULT 'started',
    end_reason           nav_end_reason,
    mode                 transport_mode NOT NULL DEFAULT 'bike',
    -- diem xuat phat luc bam nut
    origin_latitude      NUMERIC(9,6) NOT NULL,
    origin_longitude     NUMERIC(9,6) NOT NULL,
    origin_accuracy_m    REAL,
    -- tuyen duong da tinh
    route_provider       route_provider,
    route_distance_m     INTEGER,
    route_duration_s     INTEGER,
    route_polyline       TEXT,                           -- encoded polyline (precision 5/6)
    route_steps          JSONB,                          -- turn-by-turn da dich tieng Viet
    reroute_count        SMALLINT NOT NULL DEFAULT 0,
    -- theo doi di chuyen / den noi
    started_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    moving_since         TIMESTAMPTZ,                    -- thoi diem phat hien bat dau di chuyen
    near_store_since     TIMESTAMPTZ,                    -- thoi diem vao geofence lan dau
    dwell_started_at     TIMESTAMPTZ,                    -- thoi diem bat dau "dung yen" hien tai
    dwell_anchor_lat     NUMERIC(9,6),
    dwell_anchor_lng     NUMERIC(9,6),
    arrived_at           TIMESTAMPTZ,
    ended_at             TIMESTAMPTZ,
    last_ping_at         TIMESTAMPTZ,
    last_latitude        NUMERIC(9,6),
    last_longitude       NUMERIC(9,6),
    distance_to_store_m  INTEGER,                        -- cap nhat moi ping
    total_traveled_m     INTEGER NOT NULL DEFAULT 0,
    ping_count           INTEGER NOT NULL DEFAULT 0,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TRIGGER trg_nav_session_updated_at BEFORE UPDATE ON nav_session
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
-- moi user chi co TOI DA 1 phien dang hoat dong
CREATE UNIQUE INDEX uq_nav_session_active_user ON nav_session(user_id)
    WHERE status IN ('started','moving','near_store');
CREATE INDEX idx_nav_session_store   ON nav_session(store_id, started_at DESC);
CREATE INDEX idx_nav_session_status  ON nav_session(status, last_ping_at);
CREATE INDEX idx_nav_session_user    ON nav_session(user_id, started_at DESC);

CREATE TABLE location_ping (
    id            BIGSERIAL PRIMARY KEY,
    session_id    UUID NOT NULL REFERENCES nav_session(id) ON DELETE CASCADE,
    user_id       UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    latitude      NUMERIC(9,6) NOT NULL,
    longitude     NUMERIC(9,6) NOT NULL,
    accuracy_m    REAL,
    speed_mps     REAL,
    heading_deg   REAL,
    battery_pct   SMALLINT,
    is_mock       BOOLEAN NOT NULL DEFAULT FALSE,        -- phat hien fake GPS phia client
    recorded_at   TIMESTAMPTZ NOT NULL,                  -- gio tren thiet bi
    received_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_ping_session_time ON location_ping(session_id, recorded_at);
CREATE INDEX idx_ping_time_brin    ON location_ping USING BRIN (recorded_at);
COMMENT ON TABLE location_ping IS 'Ping GPS tho. Bang lon nhanh nhat: job don dep xoa/nen sau 30 ngay (xem plan.md).';

-- Chuyen di DA XAC NHAN toi quan (dung >= 10 phut trong geofence)
CREATE TABLE store_visit (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id              UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    store_id             UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    session_id           UUID UNIQUE REFERENCES nav_session(id) ON DELETE SET NULL,
    arrived_at           TIMESTAMPTZ NOT NULL,
    dwell_seconds        INTEGER NOT NULL CHECK (dwell_seconds >= 0),
    confirm_method       VARCHAR(20) NOT NULL DEFAULT 'gps_dwell' CHECK (confirm_method IN ('gps_dwell','manual','qr')),
    distance_to_store_m  INTEGER,
    travel_distance_m    INTEGER,
    travel_seconds       INTEGER,
    mode                 transport_mode,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_store_visit_user  ON store_visit(user_id, arrived_at DESC);
CREATE INDEX idx_store_visit_store ON store_visit(store_id, arrived_at DESC);

-- link review -> visit (sau khi store_visit da ton tai)
ALTER TABLE review ADD COLUMN visit_id UUID REFERENCES store_visit(id) ON DELETE SET NULL;

-- Su kien hanh vi (nguon cho store_visit_stat, hot ranking)
CREATE TABLE store_event (
    id         BIGSERIAL PRIMARY KEY,
    store_id   UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    user_id    UUID REFERENCES app_user(id) ON DELETE SET NULL,
    type       store_event_type NOT NULL,
    meta       JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_store_event_store_time ON store_event(store_id, type, created_at DESC);
CREATE INDEX idx_store_event_time_brin  ON store_event USING BRIN (created_at);

CREATE TABLE search_log (
    id          BIGSERIAL PRIMARY KEY,
    user_id     UUID REFERENCES app_user(id) ON DELETE SET NULL,
    query       VARCHAR(255) NOT NULL,
    latitude    NUMERIC(9,6),
    longitude   NUMERIC(9,6),
    filters     JSONB,
    result_count INTEGER,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_search_log_time ON search_log(created_at DESC);

-- Cache tuyen duong (giam goi OSRM, tang toc)
CREATE TABLE route_cache (
    id            BIGSERIAL PRIMARY KEY,
    cache_key     CHAR(64) NOT NULL,                    -- sha256(mode|olat,olng(lam tron 4 so)|dlat,dlng)
    mode          transport_mode NOT NULL,
    provider      route_provider NOT NULL,
    distance_m    INTEGER NOT NULL,
    duration_s    INTEGER NOT NULL,
    polyline      TEXT NOT NULL,
    steps         JSONB,
    expires_at    TIMESTAMPTZ NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_route_cache UNIQUE (cache_key)
);
CREATE INDEX idx_route_cache_exp ON route_cache(expires_at);

-- Log moi lan tinh duong (Admin RoutingNodes: latency, ty le loi)
CREATE TABLE route_request_log (
    id          BIGSERIAL PRIMARY KEY,
    user_id     UUID REFERENCES app_user(id) ON DELETE SET NULL,
    store_id    UUID REFERENCES store(id) ON DELETE SET NULL,
    mode        transport_mode NOT NULL,
    provider    route_provider NOT NULL,
    node_id     INTEGER,                                -- FK them sau (routing_node)
    cache_hit   BOOLEAN NOT NULL DEFAULT FALSE,
    success     BOOLEAN NOT NULL,
    latency_ms  INTEGER,
    distance_m  INTEGER,
    error       TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_route_log_time ON route_request_log(created_at DESC);

-- Cum node dinh tuyen (Admin: "Cum Node Dinh Tuyen")
CREATE TABLE routing_node (
    id             SERIAL PRIMARY KEY,
    name           VARCHAR(100) NOT NULL,
    provider       route_provider NOT NULL DEFAULT 'osrm',
    base_url       TEXT NOT NULL,
    region         VARCHAR(100),
    coverage_radius_km NUMERIC(6,1),
    center_latitude  NUMERIC(9,6),
    center_longitude NUMERIC(9,6),
    priority       SMALLINT NOT NULL DEFAULT 10,
    status         node_status NOT NULL DEFAULT 'online',
    last_latency_ms INTEGER,
    last_health_at TIMESTAMPTZ,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE route_request_log ADD CONSTRAINT fk_route_log_node
    FOREIGN KEY (node_id) REFERENCES routing_node(id) ON DELETE SET NULL;

-- Cau hinh nguong dong (chinh khong can deploy)
CREATE TABLE app_setting (
    key         VARCHAR(100) PRIMARY KEY,
    value       JSONB NOT NULL,
    description TEXT,
    updated_by  UUID REFERENCES app_user(id) ON DELETE SET NULL,
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- 7. NHOM TRIP / AI / CHALLENGE / LIVE
-- ============================================================================
-- 7.1 Food Tour Planner (TripPlannerPage + SavedPage)
CREATE TABLE trip (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id           UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    title             VARCHAR(255) NOT NULL,
    start_label       VARCHAR(255),
    start_latitude    NUMERIC(9,6),
    start_longitude   NUMERIC(9,6),
    dest_label        VARCHAR(255),
    dest_latitude     NUMERIC(9,6),
    dest_longitude    NUMERIC(9,6),
    vehicle           transport_mode NOT NULL DEFAULT 'car',
    status            trip_status NOT NULL DEFAULT 'draft',
    total_distance_m  INTEGER,
    total_duration_s  INTEGER,
    budget_min        INTEGER,
    budget_max        INTEGER,
    is_public         BOOLEAN NOT NULL DEFAULT FALSE,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TRIGGER trg_trip_updated_at BEFORE UPDATE ON trip
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX idx_trip_user ON trip(user_id, created_at DESC);

CREATE TABLE trip_stop (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    trip_id       UUID NOT NULL REFERENCES trip(id) ON DELETE CASCADE,
    store_id      UUID REFERENCES store(id) ON DELETE SET NULL,
    stop_order    SMALLINT NOT NULL,
    label         VARCHAR(255),
    latitude      NUMERIC(9,6) NOT NULL,
    longitude     NUMERIC(9,6) NOT NULL,
    leg_distance_m INTEGER,
    leg_duration_s INTEGER,
    planned_arrival TIMESTAMPTZ,
    visit_id      UUID REFERENCES store_visit(id) ON DELETE SET NULL,  -- tick hoan thanh khi GPS xac nhan
    CONSTRAINT uq_trip_stop_order UNIQUE (trip_id, stop_order)
);

-- 7.2 AI goi y mon (AIPage)
CREATE TABLE ai_model_config (
    id         SERIAL PRIMARY KEY,
    name       VARCHAR(100) NOT NULL,
    version    VARCHAR(30) NOT NULL,
    provider   VARCHAR(30) NOT NULL DEFAULT 'gemini',
    params     JSONB NOT NULL DEFAULT '{}',
    is_active  BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX uq_ai_model_active ON ai_model_config((TRUE)) WHERE is_active;

CREATE TABLE ai_recommendation (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id          UUID REFERENCES app_user(id) ON DELETE SET NULL,
    model_id         INTEGER REFERENCES ai_model_config(id),
    prompt_text      TEXT,
    mood_code        VARCHAR(50),
    budget_code      VARCHAR(30),
    distance_code    VARCHAR(30),
    tags             TEXT[],
    latitude         NUMERIC(9,6),
    longitude        NUMERIC(9,6),
    result_store_ids UUID[],
    result_item_ids  UUID[],
    latency_ms       INTEGER,
    feedback         SMALLINT CHECK (feedback IN (-1, 1)),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_ai_reco_user ON ai_recommendation(user_id, created_at DESC);

-- 7.3 Thu thach "Hom nay an gi" (MysteryFoodPage)
CREATE TABLE food_challenge (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    title       VARCHAR(255) NOT NULL,
    description TEXT,
    badge_name  VARCHAR(100),
    badge_icon  VARCHAR(100),
    target_count INTEGER NOT NULL DEFAULT 3,
    reward_points INTEGER NOT NULL DEFAULT 0,
    starts_at   TIMESTAMPTZ,
    ends_at     TIMESTAMPTZ,
    is_active   BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE food_challenge_store (
    challenge_id UUID NOT NULL REFERENCES food_challenge(id) ON DELETE CASCADE,
    store_id     UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    PRIMARY KEY (challenge_id, store_id)
);
CREATE TABLE user_challenge_progress (
    user_id      UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    challenge_id UUID NOT NULL REFERENCES food_challenge(id) ON DELETE CASCADE,
    store_id     UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    visit_id     UUID NOT NULL REFERENCES store_visit(id) ON DELETE CASCADE,  -- chi tinh khi GPS xac nhan da den
    completed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, challenge_id, store_id)
);
CREATE TABLE spin_history (             -- "Quay so" an gi
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    UUID REFERENCES app_user(id) ON DELETE SET NULL,
    filter     VARCHAR(30),
    store_id   UUID REFERENCES store(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 7.4 Livestream (LivePulsePage)
CREATE TABLE livestream (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id      UUID REFERENCES store(id) ON DELETE SET NULL,
    host_user_id  UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    title         VARCHAR(255) NOT NULL,
    category_id   SMALLINT REFERENCES category(id),
    stream_url    TEXT,
    thumbnail_url TEXT,
    status        live_status NOT NULL DEFAULT 'scheduled',
    viewer_peak   INTEGER NOT NULL DEFAULT 0,
    like_count    INTEGER NOT NULL DEFAULT 0,
    scheduled_at  TIMESTAMPTZ,
    started_at    TIMESTAMPTZ,
    ended_at      TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_livestream_status ON livestream(status, started_at DESC);
CREATE TABLE livestream_message (
    id            BIGSERIAL PRIMARY KEY,
    livestream_id UUID NOT NULL REFERENCES livestream(id) ON DELETE CASCADE,
    user_id       UUID REFERENCES app_user(id) ON DELETE SET NULL,
    content       VARCHAR(500) NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_live_msg ON livestream_message(livestream_id, created_at);

-- ============================================================================
-- 8. THANH TOAN / QUANG CAO / VOUCHER
-- ============================================================================
CREATE TABLE payment_transaction (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       UUID NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT,
    purpose       VARCHAR(30) NOT NULL CHECK (purpose IN ('user_premium','store_analytics','ad_campaign','topup')),
    ref_id        UUID,                                   -- id user_subscription / store_stat_subscription / ad_campaign
    amount        NUMERIC(12,2) NOT NULL CHECK (amount >= 0),
    currency      CHAR(3) NOT NULL DEFAULT 'VND',
    provider      VARCHAR(20) NOT NULL CHECK (provider IN ('vnpay','momo','zalopay','payos','bank_transfer')),
    provider_ref  VARCHAR(100),
    status        payment_status NOT NULL DEFAULT 'pending',
    raw_payload   JSONB,
    paid_at       TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_payment_provider_ref UNIQUE (provider, provider_ref)
);
CREATE INDEX idx_payment_user ON payment_transaction(user_id, created_at DESC);

CREATE TABLE invoice (                                   -- Admin: Doi soat & Hoa don VAT
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    invoice_no      VARCHAR(30) NOT NULL UNIQUE,
    payment_id      UUID REFERENCES payment_transaction(id) ON DELETE SET NULL,
    owner_id        UUID REFERENCES store_owner_profile(id) ON DELETE SET NULL,
    buyer_name      VARCHAR(255) NOT NULL,
    buyer_tax_code  VARCHAR(20),
    subtotal        NUMERIC(14,2) NOT NULL,
    vat_rate        NUMERIC(4,2) NOT NULL DEFAULT 10.00,
    vat_amount      NUMERIC(14,2) NOT NULL,
    total           NUMERIC(14,2) NOT NULL,
    status          invoice_status NOT NULL DEFAULT 'draft',
    pdf_url         TEXT,
    issued_at       TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE ad_campaign (                               -- Merchant VIP + Admin Campaigns + trang VIP
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id        UUID NOT NULL REFERENCES store(id) ON DELETE CASCADE,
    title           VARCHAR(255) NOT NULL,
    description     TEXT,
    type            ad_campaign_type NOT NULL,
    discount_value  INTEGER,                              -- % hoac VND tuy type
    voucher_code    VARCHAR(30),
    voucher_quota   INTEGER,
    require_visit   BOOLEAN NOT NULL DEFAULT FALSE,       -- check-in GPS moi dung duoc
    budget          NUMERIC(12,2) NOT NULL DEFAULT 0,
    spent           NUMERIC(12,2) NOT NULL DEFAULT 0,
    cost_per_click  NUMERIC(10,2),
    start_at        TIMESTAMPTZ NOT NULL,
    end_at          TIMESTAMPTZ NOT NULL,
    status          ad_campaign_status NOT NULL DEFAULT 'draft',
    reviewed_by     UUID REFERENCES app_user(id) ON DELETE SET NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_campaign_dates CHECK (end_at > start_at),
    CONSTRAINT chk_campaign_spent CHECK (spent <= budget OR budget = 0)
);
CREATE TRIGGER trg_ad_campaign_updated_at BEFORE UPDATE ON ad_campaign
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE INDEX idx_ad_campaign_store  ON ad_campaign(store_id);
CREATE INDEX idx_ad_campaign_active ON ad_campaign(status, start_at, end_at);

CREATE TABLE ad_event (
    id          BIGSERIAL PRIMARY KEY,
    campaign_id UUID NOT NULL REFERENCES ad_campaign(id) ON DELETE CASCADE,
    user_id     UUID REFERENCES app_user(id) ON DELETE SET NULL,
    type        ad_event_type NOT NULL,
    cost        NUMERIC(10,2) NOT NULL DEFAULT 0,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_ad_event_campaign ON ad_event(campaign_id, type, created_at);

CREATE TABLE voucher_claim (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    campaign_id  UUID NOT NULL REFERENCES ad_campaign(id) ON DELETE CASCADE,
    user_id      UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    code         VARCHAR(40) NOT NULL UNIQUE,
    status       voucher_status NOT NULL DEFAULT 'claimed',
    visit_id     UUID REFERENCES store_visit(id) ON DELETE SET NULL,
    claimed_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    redeemed_at  TIMESTAMPTZ,
    expires_at   TIMESTAMPTZ,
    CONSTRAINT uq_voucher_user_campaign UNIQUE (campaign_id, user_id)
);

-- ============================================================================
-- 9. NHOM ADMIN
-- ============================================================================
-- 9.1 Fraud / bao cao gian lan (Admin Fraud tab)
CREATE TABLE fraud_case (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    target_type   report_target_type NOT NULL,
    target_id     UUID NOT NULL,
    rule_code     VARCHAR(50) NOT NULL,        -- fake_gps, duplicate_cccd, review_farm, spam_store...
    score         NUMERIC(4,3),
    status        fraud_status NOT NULL DEFAULT 'open',
    penalty_vnd   NUMERIC(12,2),
    evidence      JSONB,
    handled_by    UUID REFERENCES app_user(id) ON DELETE SET NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    resolved_at   TIMESTAMPTZ
);
CREATE INDEX idx_fraud_status ON fraud_case(status, created_at DESC);

-- 9.2 KOL / Foodie reviewer
CREATE TABLE kol_profile (
    user_id         UUID PRIMARY KEY REFERENCES app_user(id) ON DELETE CASCADE,
    tier            kol_tier NOT NULL DEFAULT 'rookie',
    follower_count  INTEGER NOT NULL DEFAULT 0,
    commission_rate NUMERIC(4,2) NOT NULL DEFAULT 0,
    social_links    JSONB,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    approved_by     UUID REFERENCES app_user(id) ON DELETE SET NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 9.3 RBAC chi tiet cho staff/admin (Admin Roles tab)
CREATE TABLE permission (
    code        VARCHAR(80) PRIMARY KEY,
    description VARCHAR(255)
);
CREATE TABLE admin_role (
    id          SMALLSERIAL PRIMARY KEY,
    name        VARCHAR(80) NOT NULL UNIQUE,
    description VARCHAR(255)
);
CREATE TABLE admin_role_permission (
    role_id        SMALLINT NOT NULL REFERENCES admin_role(id) ON DELETE CASCADE,
    permission_code VARCHAR(80) NOT NULL REFERENCES permission(code) ON DELETE CASCADE,
    PRIMARY KEY (role_id, permission_code)
);
CREATE TABLE user_admin_role (
    user_id    UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    role_id    SMALLINT NOT NULL REFERENCES admin_role(id) ON DELETE CASCADE,
    granted_by UUID REFERENCES app_user(id) ON DELETE SET NULL,
    granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, role_id)
);
CREATE TABLE admin_ip_allowlist (
    id         SERIAL PRIMARY KEY,
    cidr       CIDR NOT NULL,
    label      VARCHAR(150),
    is_active  BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 9.4 Audit log (chuoi hash chong sua)
CREATE TABLE audit_log (
    id          BIGSERIAL PRIMARY KEY,
    actor_id    UUID REFERENCES app_user(id) ON DELETE SET NULL,
    action      VARCHAR(80) NOT NULL,
    entity      VARCHAR(60),
    entity_id   VARCHAR(64),
    before_data JSONB,
    after_data  JSONB,
    ip_address  INET,
    user_agent  TEXT,
    prev_hash   CHAR(64),
    row_hash    CHAR(64),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_audit_actor_time  ON audit_log(actor_id, created_at DESC);
CREATE INDEX idx_audit_entity      ON audit_log(entity, entity_id);

-- 9.5 API Partner & Webhooks
CREATE TABLE api_client (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name           VARCHAR(150) NOT NULL,
    owner_user_id  UUID REFERENCES app_user(id) ON DELETE SET NULL,
    key_hash       CHAR(64) NOT NULL UNIQUE,
    scopes         TEXT[] NOT NULL DEFAULT '{}',
    rate_limit_per_min INTEGER NOT NULL DEFAULT 60,
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,
    last_used_at   TIMESTAMPTZ,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE webhook_endpoint (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    client_id  UUID NOT NULL REFERENCES api_client(id) ON DELETE CASCADE,
    url        TEXT NOT NULL,
    secret     VARCHAR(100) NOT NULL,
    events     TEXT[] NOT NULL DEFAULT '{}',
    is_active  BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE webhook_delivery (
    id           BIGSERIAL PRIMARY KEY,
    endpoint_id  UUID NOT NULL REFERENCES webhook_endpoint(id) ON DELETE CASCADE,
    event        VARCHAR(80) NOT NULL,
    payload      JSONB NOT NULL,
    http_status  INTEGER,
    attempts     SMALLINT NOT NULL DEFAULT 0,
    delivered_at TIMESTAMPTZ,
    next_retry_at TIMESTAMPTZ,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_webhook_retry ON webhook_delivery(next_retry_at) WHERE delivered_at IS NULL;

-- ============================================================================
-- 10. TRIGGERS / FUNCTIONS / VIEWS NGHIEP VU
-- ============================================================================
-- 10.1 Tu dong tinh rating_avg / review_count cua store
CREATE OR REPLACE FUNCTION fn_refresh_store_rating(p_store UUID) RETURNS VOID AS $$
    UPDATE store s SET
        rating_avg   = COALESCE((SELECT ROUND(AVG(rating)::numeric,2) FROM review r
                                 WHERE r.store_id = p_store AND r.status = 'visible'), 0),
        review_count = (SELECT COUNT(*) FROM review r WHERE r.store_id = p_store AND r.status = 'visible')
    WHERE s.id = p_store;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION trg_review_refresh() RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN PERFORM fn_refresh_store_rating(OLD.store_id);
    ELSE PERFORM fn_refresh_store_rating(NEW.store_id); END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_review_rating_refresh AFTER INSERT OR UPDATE OF rating, status OR DELETE ON review
    FOR EACH ROW EXECUTE FUNCTION trg_review_refresh();

-- 10.2 Dem like review
CREATE OR REPLACE FUNCTION trg_review_like_count() RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN UPDATE review SET like_count = like_count + 1 WHERE id = NEW.review_id;
    ELSE UPDATE review SET like_count = GREATEST(like_count - 1,0) WHERE id = OLD.review_id; END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_review_like_cnt AFTER INSERT OR DELETE ON review_like
    FOR EACH ROW EXECUTE FUNCTION trg_review_like_count();

-- 10.3 Khi co store_visit moi: tang visit_count + thong ke ngay (upsert)
CREATE OR REPLACE FUNCTION trg_store_visit_after_insert() RETURNS TRIGGER AS $$
DECLARE h TEXT := to_char(NEW.arrived_at AT TIME ZONE 'Asia/Ho_Chi_Minh','FMHH24');
BEGIN
    UPDATE store SET visit_count = visit_count + 1 WHERE id = NEW.store_id;
    VALUES (NEW.store_id, (NEW.arrived_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date, 1, NEW.dwell_seconds,
            jsonb_build_object(h, 1))
    ON CONFLICT (store_id, stat_date) DO UPDATE SET
        visit_confirmed_count = store_visit_stat.visit_confirmed_count + 1,
        avg_dwell_seconds = ((COALESCE(store_visit_stat.avg_dwell_seconds,0) * store_visit_stat.visit_confirmed_count)
                              + NEW.dwell_seconds) / (store_visit_stat.visit_confirmed_count + 1),
        peak_hour_histogram = jsonb_set(COALESCE(store_visit_stat.peak_hour_histogram,'{}'::jsonb), ARRAY[h],
            to_jsonb(COALESCE((store_visit_stat.peak_hour_histogram->>h)::int,0) + 1));
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_store_visit_ai AFTER INSERT ON store_visit
    FOR EACH ROW EXECUTE FUNCTION trg_store_visit_after_insert();

-- 10.4 Khoang cach haversine (met)
CREATE OR REPLACE FUNCTION fn_haversine_m(
    lat1 DOUBLE PRECISION, lng1 DOUBLE PRECISION, lat2 DOUBLE PRECISION, lng2 DOUBLE PRECISION)
RETURNS DOUBLE PRECISION AS $$
    SELECT 2 * 6371000 * asin(sqrt(
        power(sin(radians(lat2 - lat1) / 2), 2) +
        cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2)))
$$ LANGUAGE sql IMMUTABLE PARALLEL SAFE;

-- 10.5 Tim quan gan vi tri (ban kinh met): bounding box (dung index lat/lng) roi haversine
CREATE OR REPLACE FUNCTION fn_stores_nearby(
    p_lat DOUBLE PRECISION, p_lng DOUBLE PRECISION,
    p_radius_m INTEGER DEFAULT 3000, p_limit INTEGER DEFAULT 50)
RETURNS TABLE (store_id UUID, name VARCHAR, distance_m DOUBLE PRECISION) AS $$
    SELECT s.id, s.name, d.dist
    FROM store s
    CROSS JOIN LATERAL (SELECT fn_haversine_m(p_lat, p_lng, s.latitude::float8, s.longitude::float8) AS dist) d
    WHERE s.status = 'active'
      AND s.latitude  BETWEEN p_lat - (p_radius_m / 111320.0) AND p_lat + (p_radius_m / 111320.0)
      AND s.longitude BETWEEN p_lng - (p_radius_m / (111320.0 * GREATEST(cos(radians(p_lat)), 0.01)))
                          AND p_lng + (p_radius_m / (111320.0 * GREATEST(cos(radians(p_lat)), 0.01)))
      AND d.dist <= p_radius_m
    ORDER BY d.dist
    LIMIT p_limit;
$$ LANGUAGE sql STABLE;

-- 10.6 Khoang cach (m) giua 1 diem va quan — dung cho geofence trong backend/SQL
CREATE OR REPLACE FUNCTION fn_distance_to_store_m(
    p_store UUID, p_lat DOUBLE PRECISION, p_lng DOUBLE PRECISION) RETURNS DOUBLE PRECISION AS $$
    SELECT fn_haversine_m(p_lat, p_lng, s.latitude::float8, s.longitude::float8)
    FROM store s WHERE s.id = p_store;
$$ LANGUAGE sql STABLE;

-- 10.6 Ranking HOT (24h / tuan / thang) = vote + visit + route + save, trong so cau hinh duoc
CREATE OR REPLACE VIEW v_store_hot_score AS
SELECT s.id AS store_id,
       s.name,
       COALESCE(v24.c,0) AS votes_24h,
       COALESCE(v7.c,0)  AS votes_7d,
       COALESCE(v30.c,0) AS votes_30d,
       COALESCE(e7.visits,0) AS visits_7d,
       COALESCE(e7.routes,0) AS routes_7d,
       (COALESCE(v7.c,0)*1.0 + COALESCE(e7.visits,0)*3.0 + COALESCE(e7.routes,0)*0.5) AS hot_score_7d
FROM store s
LEFT JOIN (SELECT store_id, COUNT(*) c FROM store_vote WHERE created_at > now() - interval '24 hours' GROUP BY store_id) v24 ON v24.store_id = s.id
LEFT JOIN (SELECT store_id, COUNT(*) c FROM store_vote WHERE created_at > now() - interval '7 days'   GROUP BY store_id) v7  ON v7.store_id  = s.id
LEFT JOIN (SELECT store_id, COUNT(*) c FROM store_vote WHERE created_at > now() - interval '30 days'  GROUP BY store_id) v30 ON v30.store_id = s.id
LEFT JOIN (SELECT store_id,
                  COUNT(*) FILTER (WHERE type='arrive') visits,
                  COUNT(*) FILTER (WHERE type='route_request') routes
           FROM store_event WHERE created_at > now() - interval '7 days' GROUP BY store_id) e7 ON e7.store_id = s.id
WHERE s.status = 'active';

-- 10.7 Thong ke cho Admin Live Map: nguoi dang di chuyen
CREATE OR REPLACE VIEW v_live_navigation AS
SELECT n.id AS session_id, n.user_id, n.store_id, n.status, n.mode,
       n.last_latitude, n.last_longitude, n.distance_to_store_m, n.last_ping_at
FROM nav_session n
WHERE n.status IN ('started','moving','near_store')
  AND n.last_ping_at > now() - interval '2 minutes';

